import React, { useState, useEffect } from "react";
import axios from "axios";
import "./styles.css";

// Create axios instance with auth header
const api = axios.create({
  baseURL: "http://localhost:8000",
});

// Add interceptor to include token in requests
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

function App() {
  const [username, setUsername] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [loginIdentifier, setLoginIdentifier] = useState(""); // username or email
  const [message, setMessage] = useState("");
  const [googleUser, setGoogleUser] = useState(null);
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [profile, setProfile] = useState(null);
  const [isLoggedIn, setIsLoggedIn] = useState(!!localStorage.getItem("token"));
  const [currentPage, setCurrentPage] = useState("login"); // "login" or "register"
  const [showForgot, setShowForgot] = useState(false);
  const [resetStep, setResetStep] = useState(1); // 1: send code, 2: enter code + new pw
  const [resetEmail, setResetEmail] = useState("");
  const [resetCode, setResetCode] = useState("");
  const [resetNewPassword, setResetNewPassword] = useState("");
  const [resetConfirmNewPassword, setResetConfirmNewPassword] = useState("");
  
  // Loading states
  const [isLoading, setIsLoading] = useState(false);
  const [isLoginLoading, setIsLoginLoading] = useState(false);
  const [isRegisterLoading, setIsRegisterLoading] = useState(false);
  const [isResetLoading, setIsResetLoading] = useState(false);

  // Validation helpers
  const isEmailValid = (value) => /[^\s@]+@[^\s@]+\.[^\s@]+/.test(value);
  const passHasLen = password.length >= 8;
  const passHasUpper = /[A-Z]/.test(password);
  const passHasLower = /[a-z]/.test(password);
  const passHasNumber = /\d/.test(password);
  const passHasSpecial = /[^A-Za-z0-9]/.test(password);
  const isPasswordStrong = passHasLen && passHasUpper && passHasLower && passHasNumber && passHasSpecial;

  // Reset password validators
  const rPassHasLen = resetNewPassword.length >= 8;
  const rPassHasUpper = /[A-Z]/.test(resetNewPassword);
  const rPassHasLower = /[a-z]/.test(resetNewPassword);
  const rPassHasNumber = /\d/.test(resetNewPassword);
  const rPassHasSpecial = /[^A-Za-z0-9]/.test(resetNewPassword);
  const isResetPasswordStrong = rPassHasLen && rPassHasUpper && rPassHasLower && rPassHasNumber && rPassHasSpecial;

  // Show success message with auto-clear
  const showSuccessMessage = (msg) => {
    setMessage(msg);
    setTimeout(() => setMessage(""), 5000);
  };

  // Show error message with auto-clear
  const showErrorMessage = (msg) => {
    setMessage(msg);
    setTimeout(() => setMessage(""), 7000);
  };

  const register = async () => {
    if (!username || !email || !password || !confirmPassword) {
      showErrorMessage("All fields are required");
      return;
    }

    if (!isEmailValid(email)) {
      showErrorMessage("Please enter a valid email address");
      return;
    }

    if (password !== confirmPassword) {
      showErrorMessage("Passwords do not match");
      return;
    }

    if (!isPasswordStrong) {
      showErrorMessage("Please meet the password requirements below");
      return;
    }

    setIsRegisterLoading(true);
    try {
      await axios.post("http://localhost:8000/register", {
        username,
        email,
        password,
      });
      
      // Show success message and redirect to login page
      showSuccessMessage("Registration successful! Please login with your credentials.");
      setCurrentPage("login");
      
      // Clear form fields
      setUsername("");
      setEmail("");
      setPassword("");
      setConfirmPassword("");
      
    } catch (err) {
      showErrorMessage(err.response?.data?.detail || "Error registering");
    } finally {
      setIsRegisterLoading(false);
    }
  };

  const login = async () => {
    if (!loginIdentifier || !password) {
      showErrorMessage("Please enter your username or email and password");
      return;
    }
    
    setIsLoginLoading(true);
    try {
      const payload = loginIdentifier.includes("@")
        ? { email: loginIdentifier, password }
        : { username: loginIdentifier, password };
      const res = await axios.post("http://localhost:8000/login", payload);

      // Save token
      const { access_token, message: resMessage } = res.data;
      localStorage.setItem("token", access_token);
      setToken(access_token);
      setIsLoggedIn(true);
      showSuccessMessage(resMessage);

      // Fetch user profile
      fetchProfile();
    } catch (err) {
      showErrorMessage(err.response?.data?.detail || "Error logging in");
    } finally {
      setIsLoginLoading(false);
    }
  };

  const logout = () => {
    localStorage.removeItem("token");
    setToken("");
    setIsLoggedIn(false);
    setProfile(null);
    setGoogleUser(null);
    showSuccessMessage("Logged out successfully");
    setCurrentPage("login");
    setShowForgot(false);
    setLoginIdentifier("");
    setPassword("");
  };

  const fetchProfile = async () => {
    setIsLoading(true);
    try {
      const res = await api.get("/profile");
      setProfile(res.data);
    } catch (err) {
      console.error("Error fetching profile:", err);
      if (err.response?.status === 401) {
        // Token expired or invalid
        logout();
      }
    } finally {
      setIsLoading(false);
    }
  };

  // Render the reset password form
  const renderResetPasswordForm = () => (
    <div className="auth-page">
      <h2 className="auth-title">Reset Password</h2>

      {resetStep === 1 ? (
        <>
          <p className="auth-subtitle">Enter your email to receive a verification code</p>
          <div className="form-group">
            <label>Email Address</label>
            <div className="input-wrapper">
              <svg className="input-prefix" width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M20 4H4C2.9 4 2 4.9 2 6V18C2 19.1 2.9 20 4 20H20C21.1 20 22 19.1 22 18V6C22 4.9 21.1 4 20 4ZM20 8L12 13L4 8V6L12 11L20 6V8Z" fill="#6B7280"/>
              </svg>
              <input
                type="email"
                value={resetEmail}
                onChange={(e) => setResetEmail(e.target.value)}
                className="input-field"
                placeholder="Enter your email"
                disabled={isResetLoading}
              />
            </div>
          </div>
          <button 
            onClick={sendResetCode} 
            className="btn btn-primary"
            disabled={isResetLoading || !isEmailValid(resetEmail)}
          >
            {isResetLoading ? 'Sending...' : 'Send Verification Code'}
          </button>
          <p className="auth-footer">
            Remember your password?{' '}
            <button 
              type="button" 
              className="btn-text"
              onClick={() => setShowForgot(false)}
              disabled={isLoading}
            >
              Back to login
            </button>
          </p>
        </>
      ) : (
        <>
          <p className="auth-subtitle">Enter the code sent to {resetEmail} and your new password</p>

          <div className="form-group">
            <label>Verification Code</label>
            <div className="input-wrapper">
              <svg className="input-prefix" width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M12 1L3 5V11C3 16.55 6.16 21.74 12 23C17.84 21.74 21 16.55 21 11V5L12 1ZM19 11C19 15.52 16.02 20.19 12 21.32C7.98 20.19 5 15.53 5 11V6.3L12 3.19L19 6.3V11Z" fill="#6B7280"/>
                <path d="M12 11.86L8.24 8.1L6.83 9.51L12 14.68L19.9 6.78L18.49 5.37L12 11.86Z" fill="#6B7280"/>
              </svg>
              <input
                type="text"
                value={resetCode}
                onChange={(e) => setResetCode(e.target.value)}
                className="input-field"
                placeholder="Enter 6-digit code"
                disabled={isResetLoading}
              />
            </div>
          </div>

          <div className="form-group">
            <label>New Password</label>
            <div className="input-wrapper">
              <svg className="input-prefix" width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M18 8H17V6C17 3.24 14.76 1 12 1C9.24 1 7 3.24 7 6V8H6C4.9 8 4 8.9 4 10V20C4 21.1 4.9 22 6 22H18C19.1 22 20 21.1 20 20V10C20 8.9 19.1 8 18 8ZM12 17C10.9 17 10 16.1 10 15C10 13.9 10.9 13 12 13C13.1 13 14 13.9 14 15C14 16.1 13.1 17 12 17ZM15.1 8H8.9V6C8.9 4.29 10.29 2.9 12 2.9C13.71 2.9 15.1 4.29 15.1 6V8Z" fill="#6B7280"/>
              </svg>
              <input
                type="password"
                value={resetNewPassword}
                onChange={(e) => setResetNewPassword(e.target.value)}
                className="input-field"
                placeholder="Create a new password"
                disabled={isResetLoading}
              />
            </div>
            <div className="password-strength">
              <div className={`strength-meter ${rPassHasLen ? 'strong' : 'weak'}`}></div>
              <div className="strength-text">
                {!rPassHasLen ? 'Weak' : rPassHasUpper && rPassHasLower && rPassHasNumber && rPassHasSpecial ? 'Strong' : 'Moderate'}
              </div>
            </div>
          </div>

          <div className="form-group">
            <label>Confirm New Password</label>
            <div className="input-wrapper">
              <svg className="input-prefix" width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M18 8H17V6C17 3.24 14.76 1 12 1C9.24 1 7 3.24 7 6V8H6C4.9 8 4 8.9 4 10V20C4 21.1 4.9 22 6 22H18C19.1 22 20 21.1 20 20V10C20 8.9 19.1 8 18 8ZM12 17C10.9 17 10 16.1 10 15C10 13.9 10.9 13 12 13C13.1 13 14 13.9 14 15C14 16.1 13.1 17 12 17ZM15.1 8H8.9V6C8.9 4.29 10.29 2.9 12 2.9C13.71 2.9 15.1 4.29 15.1 6V8Z" fill="#6B7280"/>
              </svg>
              <input
                type="password"
                value={resetConfirmNewPassword}
                onChange={(e) => setResetConfirmNewPassword(e.target.value)}
                className="input-field"
                placeholder="Confirm your new password"
                onKeyPress={(e) => e.key === 'Enter' && resetPassword()}
                disabled={isResetLoading}
              />
            </div>
            {resetConfirmNewPassword && (
              <div className={`password-match ${resetNewPassword === resetConfirmNewPassword ? 'valid' : 'invalid'}`}>
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M9 16.17L4.83 12L3.41 13.41L9 19L21 7L19.59 5.59L9 16.17Z" fill={resetNewPassword === resetConfirmNewPassword ? '#10B981' : '#EF4444'}/>
                </svg>
                {resetNewPassword === resetConfirmNewPassword ? 'Passwords match' : 'Passwords do not match'}
              </div>
            )}
          </div>

          <button 
            onClick={resetPassword} 
            className="btn btn-primary"
            disabled={isResetLoading || !resetCode || !isResetPasswordStrong || resetNewPassword !== resetConfirmNewPassword}
          >
            {isResetLoading ? 'Resetting...' : 'Reset Password'}
          </button>

          <p className="auth-footer">
            Didn't receive a code?{' '}
            <button 
              type="button" 
              className="btn-text"
              onClick={() => setResetStep(1)}
              disabled={isResetLoading}
            >
              Resend code
            </button>
          </p>
        </>
      )}
    </div>
  );

  // Forgot password flow
  const sendResetCode = async () => {
    if (!resetEmail || !isEmailValid(resetEmail)) {
      showErrorMessage("Please enter a valid email address");
      return;
    }

    setIsResetLoading(true);
    try {
      await axios.post("http://localhost:8000/forgot-password", { email: resetEmail });
      showSuccessMessage("If the email exists, a reset code has been sent. Check your inbox.");
      setResetStep(2);
    } catch (err) {
      // Always show success message to prevent email enumeration
      showSuccessMessage("If the email exists, a reset code has been sent. Check your inbox.");
      setResetStep(2);
    } finally {
      setIsResetLoading(false);
    }
  };

  const resetPassword = async () => {
    if (!resetCode || !resetNewPassword || !resetConfirmNewPassword) {
      showErrorMessage("All fields are required");
      return;
    }
    if (resetNewPassword !== resetConfirmNewPassword) {
      showErrorMessage("Passwords do not match");
      return;
    }
    if (!isResetPasswordStrong) {
      showErrorMessage("Please meet the password requirements below");
      return;
    }

    setIsResetLoading(true);
    try {
      await axios.post("http://localhost:8000/reset-password", {
        email: resetEmail,
        code: resetCode,
        new_password: resetNewPassword,
      });
      showSuccessMessage("Password reset successful. Please login with your new password.");
      // Reset forgot state and go back to login
      setShowForgot(false);
      setCurrentPage("login");
      setLoginIdentifier(resetEmail); // prefill email
      setResetEmail("");
      setResetCode("");
      setResetNewPassword("");
      setResetConfirmNewPassword("");
    } catch (err) {
      showErrorMessage(err.response?.data?.detail || "Unable to reset password. Check your code and try again.");
    } finally {
      setIsResetLoading(false);
    }
  };

  // Handle Google Sign-In response
  const handleGoogleResponse = async (response) => {
    setIsLoading(true);
    try {
      const credential = response.credential;
      const payload = JSON.parse(atob(credential.split('.')[1]));

      // Extract user info from the JWT payload
      const googleUserInfo = {
        email: payload.email,
        name: payload.name
      };

      setGoogleUser(googleUserInfo);

      // Send to backend
      const res = await axios.post("http://localhost:8000/google-login", googleUserInfo);

      // Save token
      const { access_token, message: resMessage } = res.data;
      localStorage.setItem("token", access_token);
      setToken(access_token);
      setIsLoggedIn(true);
      showSuccessMessage(resMessage);

      // Fetch user profile
      fetchProfile();
    } catch (err) {
      showErrorMessage(err.response?.data?.detail || "Error with Google Sign-In");
    } finally {
      setIsLoading(false);
    }
  };

  // Initialize Google Sign-In
  useEffect(() => {
    // Fetch Google Client ID from backend
    const fetchGoogleClientId = async () => {
      try {
        const response = await axios.get("http://localhost:8000/google-client-id");
        const clientId = response.data.client_id;

        if (window.google && clientId) {
          window.google.accounts.id.initialize({
            client_id: clientId,
            callback: handleGoogleResponse,
          });

          window.google.accounts.id.renderButton(
            document.getElementById("google-signin"),
            { theme: "outline", size: "large", text: "signin_with", shape: "rectangular" }
          );
        }
      } catch (err) {
        console.error("Error fetching Google Client ID:", err);
        showErrorMessage("Error initializing Google Sign-In");
      }
    };

    fetchGoogleClientId();
  }, []);

  // Fetch user profile on component mount if token exists
  useEffect(() => {
    if (token) {
      fetchProfile();
    }
  }, []);

  // Determine message class based on content
  const getMessageClass = () => {
    if (!message) return "";
    return message.toLowerCase().includes("error") ? "message error" : "message success";
  };

  // Clear message when switching pages
  const switchToPage = (page) => {
    setCurrentPage(page);
    setMessage("");
    setUsername("");
    setEmail("");
    setPassword("");
    setConfirmPassword("");
    setLoginIdentifier("");
    setShowForgot(false);
    setResetStep(1);
    setResetEmail("");
    setResetCode("");
    setResetNewPassword("");
    setResetConfirmNewPassword("");
  };

  // Loading spinner component
  const LoadingSpinner = () => (
    <div className="loading-spinner">
      <div className="spinner"></div>
    </div>
  );

  // Render the registration form
  const renderRegisterForm = () => (
    <div className="auth-page">
      <h2 className="auth-title">Create Account</h2>
      <p className="auth-subtitle">Join us to get started</p>
      <div className="input-group">
        <label className="input-label">Username</label>
        <input
          className="input-field"
          placeholder="Choose a username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          disabled={isRegisterLoading}
        />
      </div>
      <div className="input-group">
        <label className="input-label">Email</label>
        <div className="input-wrapper">
          <svg className="input-prefix" width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M20 4H4C2.9 4 2 4.9 2 6V18C2 19.1 2.9 20 4 20H20C21.1 20 22 19.1 22 18V6C22 4.9 21.1 4 20 4ZM20 8L12 13L4 8V6L12 11L20 6V8Z" fill="#6B7280"/>
          </svg>
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="input-field"
            placeholder="Enter your email"
            disabled={isRegisterLoading}
          />
        </div>
      </div>

      <div className="form-group">
        <label>Password</label>
        <div className="input-wrapper">
          <svg className="input-prefix" width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M18 8H17V6C17 3.24 14.76 1 12 1C9.24 1 7 3.24 7 6V8H6C4.9 8 4 8.9 4 10V20C4 21.1 4.9 22 6 22H18C19.1 22 20 21.1 20 20V10C20 8.9 19.1 8 18 8ZM12 17C10.9 17 10 16.1 10 15C10 13.9 10.9 13 12 13C13.1 13 14 13.9 14 15C14 16.1 13.1 17 12 17ZM15.1 8H8.9V6C8.9 4.29 10.29 2.9 12 2.9C13.71 2.9 15.1 4.29 15.1 6V8Z" fill="#6B7280"/>
          </svg>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="input-field"
            placeholder="Create a password"
          />
        </div>
        <div className="password-strength">
          <div className={`strength-meter ${passHasLen ? 'strong' : 'weak'}`}></div>
          <div className="strength-text">
            {!passHasLen ? 'Weak' : passHasUpper && passHasLower && passHasNumber && passHasSpecial ? 'Strong' : 'Moderate'}
          </div>
        </div>
        <ul className="password-requirements">
          <li className={passHasLen ? 'valid' : ''}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M9 16.17L4.83 12L3.41 13.41L9 19L21 7L19.59 5.59L9 16.17Z" fill={passHasLen ? '#10B981' : '#9CA3AF'}/>
            </svg>
            At least 8 characters
          </li>
          <li className={passHasUpper ? 'valid' : ''}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M9 16.17L4.83 12L3.41 13.41L9 19L21 7L19.59 5.59L9 16.17Z" fill={passHasUpper ? '#10B981' : '#9CA3AF'}/>
            </svg>
            Uppercase letter
          </li>
          <li className={passHasLower ? 'valid' : ''}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M9 16.17L4.83 12L3.41 13.41L9 19L21 7L19.59 5.59L9 16.17Z" fill={passHasLower ? '#10B981' : '#9CA3AF'}/>
            </svg>
            Lowercase letter
          </li>
          <li className={passHasNumber ? 'valid' : ''}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M9 16.17L4.83 12L3.41 13.41L9 19L21 7L19.59 5.59L9 16.17Z" fill={passHasNumber ? '#10B981' : '#9CA3AF'}/>
            </svg>
            Number (0-9)
          </li>
          <li className={passHasSpecial ? 'valid' : ''}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M9 16.17L4.83 12L3.41 13.41L9 19L21 7L19.59 5.59L9 16.17Z" fill={passHasSpecial ? '#10B981' : '#9CA3AF'}/>
            </svg>
            Special character (!@#$%^&*)
          </li>
        </ul>
      </div>

      <div className="form-group">
        <label>Confirm Password</label>
        <div className="input-wrapper">
          <svg className="input-prefix" width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M18 8H17V6C17 3.24 14.76 1 12 1C9.24 1 7 3.24 7 6V8H6C4.9 8 4 8.9 4 10V20C4 21.1 4.9 22 6 22H18C19.1 22 20 21.1 20 20V10C20 8.9 19.1 8 18 8ZM12 17C10.9 17 10 16.1 10 15C10 13.9 10.9 13 12 13C13.1 13 14 13.9 14 15C14 16.1 13.1 17 12 17ZM15.1 8H8.9V6C8.9 4.29 10.29 2.9 12 2.9C13.71 2.9 15.1 4.29 15.1 6V8Z" fill="#6B7280"/>
          </svg>
          <input
            type="password"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            className="input-field"
            placeholder="Confirm your password"
            onKeyPress={(e) => e.key === 'Enter' && register()}
          />
        </div>
        {confirmPassword && (
          <div className={`password-match ${password === confirmPassword ? 'valid' : 'invalid'}`}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M9 16.17L4.83 12L3.41 13.41L9 19L21 7L19.59 5.59L9 16.17Z" fill={password === confirmPassword ? '#10B981' : '#EF4444'}/>
            </svg>
            {password === confirmPassword ? 'Passwords match' : 'Passwords do not match'}
          </div>
        )}
      </div>

      <button 
        onClick={register} 
        className="btn btn-primary"
        disabled={isRegisterLoading || !isFormValid()}
      >
        {isRegisterLoading ? (
          <>
            <span className="spinner"></span>
            Creating Account...
          </>
        ) : 'Create Account'}
      </button>

      <p className="auth-footer">
        Already have an account?{' '}
        <button 
          type="button" 
          className="btn-text"
          onClick={() => setCurrentPage('login')}
          disabled={isLoading}
        >
          Sign in
        </button>
      </p>
    </div>
  );

  return (
    <div className="container">
      <h1 className="app-title">Welcome</h1>

      {!isLoggedIn ? (
        // Authentication Pages
        <>
          {/* Page Navigation */}
          <div className="page-tabs">
            <button 
              className={`tab-button ${currentPage === "login" ? "active" : ""}`}
              onClick={() => switchToPage("login")}
              disabled={isLoading}
            >
              Login
            </button>
            <button 
              className={`tab-button ${currentPage === "register" ? "active" : ""}`}
              onClick={() => switchToPage("register")}
              disabled={isLoading}
            >
              Register
            </button>
          </div>

          {currentPage === "login" ? (
            // Login or Forgot Password Page
            <div className="auth-page">
              {!showForgot ? (
                <>
                  <h2 className="page-title">Welcome Back!</h2>
                  <p className="page-description">Sign in with your username or email</p>

                  <div className="input-group">
                    <label className="input-label">Username or Email</label>
                    <input
                      className="input-field"
                      placeholder="Enter your username or email"
                      value={loginIdentifier}
                      onChange={(e) => setLoginIdentifier(e.target.value)}
                      disabled={isLoginLoading}
                    />
                  </div>

                  <div className="input-group">
                    <label className="input-label">Password</label>
                    <input
                      className="input-field"
                      type="password"
                      placeholder="Enter your password"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      disabled={isLoginLoading}
                    />
                  </div>

                  <button 
                    className="btn btn-primary login-btn" 
                    onClick={login}
                    disabled={isLoginLoading}
                  >
                    {isLoginLoading ? <LoadingSpinner /> : "Sign In"}
                  </button>

                  <div className="login-link">
                    <button 
                      className="link-button" 
                      onClick={() => { setShowForgot(true); setMessage(""); }}
                      disabled={isLoading}
                    >
                      Forgot password?
                    </button>
                  </div>

                  <div className="divider">
                    <span>OR</span>
                  </div>

                  <div className="google-signin-container">
                    <div id="google-signin"></div>
                  </div>
                </>
              ) : (
                <>
                  <h2 className="page-title">Reset your password</h2>
                  {resetStep === 1 ? (
                    <>
                      <p className="page-description">Enter your account email to receive a 6-digit code</p>
                      <div className="input-group">
                        <label className="input-label">Email</label>
                        <input
                          className="input-field"
                          type="email"
                          placeholder="you@example.com"
                          value={resetEmail}
                          onChange={(e) => setResetEmail(e.target.value)}
                          disabled={isResetLoading}
                        />
                      </div>
                      <button 
                        className="btn btn-primary login-btn" 
                        onClick={sendResetCode}
                        disabled={isResetLoading}
                      >
                        {isResetLoading ? <LoadingSpinner /> : "Send Reset Code"}
                      </button>
                      <div className="login-link">
                        <button 
                          className="link-button" 
                          onClick={() => setShowForgot(false)}
                          disabled={isLoading}
                        >
                          Back to login
                        </button>
                      </div>
                    </>
                  ) : (
                    <>
                      <p className="page-description">Enter the code sent to your email and set a new password</p>
                      <div className="input-group">
                        <label className="input-label">Verification Code</label>
                        <input
                          className="input-field"
                          placeholder="6-digit code"
                          value={resetCode}
                          onChange={(e) => setResetCode(e.target.value)}
                          disabled={isResetLoading}
                        />
                      </div>
                      <div className="input-group">
                        <label className="input-label">New Password</label>
                        <input
                          className="input-field"
                          type="password"
                          placeholder="Create a strong password"
                          value={resetNewPassword}
                          onChange={(e) => setResetNewPassword(e.target.value)}
                          disabled={isResetLoading}
                        />
                        <ul className="requirements-list">
                          <li className={`req-item ${rPassHasLen ? 'pass' : 'fail'}`}>At least 8 characters</li>
                          <li className={`req-item ${rPassHasUpper ? 'pass' : 'fail'}`}>One uppercase letter (A-Z)</li>
                          <li className={`req-item ${rPassHasLower ? 'pass' : 'fail'}`}>One lowercase letter (a-z)</li>
                          <li className={`req-item ${rPassHasNumber ? 'pass' : 'fail'}`}>One number (0-9)</li>
                          <li className={`req-item ${rPassHasSpecial ? 'pass' : 'fail'}`}>One special character (!@#$…)</li>
                        </ul>
                      </div>
                      <div className="input-group">
                        <label className="input-label">Confirm New Password</label>
                        <input
                          className="input-field"
                          type="password"
                          placeholder="Confirm your new password"
                          value={resetConfirmNewPassword}
                          onChange={(e) => setResetConfirmNewPassword(e.target.value)}
                          disabled={isResetLoading}
                        />
                      </div>
                      <button 
                        className="btn btn-primary login-btn" 
                        onClick={resetPassword}
                        disabled={isResetLoading}
                      >
                        {isResetLoading ? <LoadingSpinner /> : "Reset Password"}
                      </button>
                      <div className="login-link">
                        <button 
                          className="link-button" 
                          onClick={() => { setShowForgot(false); setResetStep(1); }}
                          disabled={isLoading}
                        >
                          Back to login
                        </button>
                      </div>
                    </>
                  )}
                </>
              )}
            </div>
          ) : (
            // Register Page
            <div className="auth-page">
              <h2 className="page-title">Create Account</h2>
              <p className="page-description">Join us and start your journey</p>

              <div className="input-group">
                <label className="input-label">Username</label>
                <input
                  className="input-field"
                  placeholder="Choose a username"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  disabled={isRegisterLoading}
                />
              </div>

              <div className="input-group">
                <label className="input-label">Email</label>
                <input
                  className="input-field"
                  type="email"
                  placeholder="you@example.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  disabled={isRegisterLoading}
                />
                {email && (
                  <div className={`helper-text ${isEmailValid(email) ? 'valid' : 'invalid'}`}>
                    {isEmailValid(email) ? '✓ Email looks good' : '✗ Enter a valid email address'}
                  </div>
                )}
              </div>

              <div className="input-group">
                <label className="input-label">Password</label>
                <input
                  className="input-field"
                  type="password"
                  placeholder="Create a strong password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  disabled={isRegisterLoading}
                />
                <ul className="requirements-list">
                  <li className={`req-item ${passHasLen ? 'pass' : 'fail'}`}>At least 8 characters</li>
                  <li className={`req-item ${passHasUpper ? 'pass' : 'fail'}`}>One uppercase letter (A-Z)</li>
                  <li className={`req-item ${passHasLower ? 'pass' : 'fail'}`}>One lowercase letter (a-z)</li>
                  <li className={`req-item ${passHasNumber ? 'pass' : 'fail'}`}>One number (0-9)</li>
                  <li className={`req-item ${passHasSpecial ? 'pass' : 'fail'}`}>One special character (!@#$…)</li>
                </ul>
              </div>

              <div className="input-group">
                <label className="input-label">Confirm Password</label>
                <input
                  className="input-field"
                  type="password"
                  placeholder="Confirm your password"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  disabled={isRegisterLoading}
                />
                {confirmPassword && (
                  <div className={`helper-text ${password && confirmPassword === password ? 'valid' : 'invalid'}`}>
                    {password && confirmPassword === password ? '✓ Passwords match' : '✗ Passwords do not match'}
                  </div>
                )}
              </div>

              <button 
                className="btn btn-secondary register-btn" 
                onClick={register}
                disabled={isRegisterLoading}
              >
                {isRegisterLoading ? <LoadingSpinner /> : "Create Account"}
              </button>

              <p className="login-link">
                Already have an account?{" "}
                <button 
                  className="link-button" 
                  onClick={() => switchToPage("login")}
                  disabled={isLoading}
                >
                  Sign in here
                </button>
              </p>
            </div>
          )}
        </>
      ) : (
        // User Profile
        <div className="profile-container">
          <h2>User Profile</h2>
          {isLoading ? (
            <div className="loading-container">
              <LoadingSpinner />
              <p>Loading profile...</p>
            </div>
          ) : profile ? (
            <div className="profile-info">
              {profile.username && <p><strong>Username:</strong> {profile.username}</p>}
              {profile.name && <p><strong>Name:</strong> {profile.name}</p>}
              {profile.email && <p><strong>Email:</strong> {profile.email}</p>}
              <p><strong>Auth Type:</strong> {profile.auth_type}</p>
              <button className="btn btn-danger" onClick={logout}>Logout</button>
            </div>
          ) : (
            <p>Unable to load profile</p>
          )}
          {renderLoginForm()}
        </div>
      )}

      {message && <div className={getMessageClass()}>{message}</div>}

      {googleUser && !profile && (
        <div className="user-info">
          <h3>Signed in Successfully</h3>
          <p>Welcome, <strong>{googleUser.name}</strong></p>
          <p className="user-email">{googleUser.email}</p>
        </div>
      )}
    </div>
  );
}

export default App;
